driverScript:
module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus("connecting", "Connecting to vMix TCP...");
    },
    onTransportReady: function(transport, config) {
        engine.setStatus("connected", "vMix TCP Ready");
        transport.send("SUBSCRIBE TALLY\r\n");
        transport.send("TALLY\r\n");
    },
    onHeartbeat: function(transport) {
        transport.send("TALLY\r\n");
    },
    onAction: function(transport, actionId, params) {
        if (actionId === "vmix_cut" || actionId === "cut") {
            transport.send("FUNCTION Cut\r\n");
            return "Cut Executed";
        }
        if (actionId === "vmix_fade" || actionId === "fade") {
            var dur = params.duration || "500";
            transport.send("FUNCTION Fade Duration=" + dur + "\r\n");
            return "Fade " + dur + "ms Executed";
        }
        if (actionId === "vmix_preview_input" || actionId === "preview") {
            var input = params.input_number || "1";
            transport.send("FUNCTION PreviewInput Input=" + input + "\r\n");
            return "Preview Input " + input;
        }
        if (actionId === "vmix_active_input" || actionId === "active") {
            var input = params.input_number || "1";
            transport.send("FUNCTION ActiveInput Input=" + input + "\r\n");
            return "Program Input " + input;
        }
        return "vMix Action Sent";
    },
    onMessage: function(transport, text, bytes) {
        if (!text) return;
        var clean = text.trim();
        if (clean.indexOf("TALLY OK ") === 0) {
            var tallyStr = clean.substring(9);
            for (var i = 0; i < tallyStr.length; i++) {
                var code = tallyStr.charAt(i);
                var inputNum = i + 1;
                var state = "OFF";
                if (code === "1") {
                    state = "PROGRAM";
                    engine.setVariable("vmix_program_input", String(inputNum));
                } else if (code === "2") {
                    state = "PREVIEW";
                    engine.setVariable("vmix_preview_input", String(inputNum));
                }
                engine.setVariable("vmix_input_" + inputNum + "_tally", state);
            }
        }
    }
};
